package com.hbm.client.silex;
import com.hbm.machine.silex.*;import mezz.jei.api.*;import mezz.jei.api.gui.builder.IRecipeLayoutBuilder;import mezz.jei.api.gui.drawable.IDrawable;import mezz.jei.api.gui.ingredient.IRecipeSlotsView;import mezz.jei.api.helpers.IGuiHelper;import mezz.jei.api.recipe.*;import mezz.jei.api.recipe.category.IRecipeCategory;import mezz.jei.api.registration.*;import net.minecraft.client.Minecraft;import net.minecraft.client.gui.GuiGraphics;import net.minecraft.network.chat.Component;import net.minecraft.resources.ResourceLocation;import net.minecraft.world.item.ItemStack;
@JeiPlugin public final class SilexJeiPlugin implements IModPlugin {
 static final RecipeType<SilexRecipe> TYPE=RecipeType.create("hbm","silex",SilexRecipe.class);@Override public ResourceLocation getPluginUid(){return SilexContent.id("silex_jei");}@Override public void registerCategories(IRecipeCategoryRegistration event){event.addRecipeCategories(new Category(event.getJeiHelpers().getGuiHelper()));}@Override public void registerRecipes(IRecipeRegistration event){var level=Minecraft.getInstance().level;if(level!=null)event.addRecipes(TYPE,SilexRecipes.recipes(level.getRecipeManager()));}@Override public void registerRecipeCatalysts(IRecipeCatalystRegistration event){event.addRecipeCatalysts(TYPE,SilexContent.ITEM.get());}@Override public void registerGuiHandlers(IGuiHandlerRegistration event){event.addRecipeClickArea(SilexScreen.class,39,60,60,50,TYPE);}
 private static final class Category implements IRecipeCategory<SilexRecipe>{private final IDrawable background,icon;Category(IGuiHelper helper){background=helper.createBlankDrawable(176,83);icon=helper.createDrawableItemStack(new ItemStack(SilexContent.ITEM.get()));}@Override public RecipeType<SilexRecipe> getRecipeType(){return TYPE;}@Override public Component getTitle(){return Component.translatable("jei.hbm.silex");}@Override public IDrawable getBackground(){return background;}@Override public IDrawable getIcon(){return icon;}@Override public void setRecipe(IRecipeLayoutBuilder builder,SilexRecipe recipe,IFocusGroup focus){builder.addSlot(RecipeIngredientRole.INPUT,12,24).addItemStacks(SilexViews.inputs(recipe));var positions=SilexViews.outputs(recipe);for(int i=0;i<positions.length;i++)builder.addSlot(RecipeIngredientRole.OUTPUT,positions[i][0],positions[i][1]).addItemStack(recipe.choices().get(i).stack());}@Override public void draw(SilexRecipe recipe,IRecipeSlotsView slots,GuiGraphics graphics,double x,double y){SilexViews.draw(recipe,graphics,0,0);}}
}
